    ('1758f6e8-4518-43fb-a14a-1ce52caca683'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd5-2026-10-25p-s001-rollback:1758f6e8-4518-43fb-a14a-1ce52caca683:period_name', 'rollback of fields-wd5-2026-10-25p-s001: period_name ''4500 - 3000 BC'' restored on Dolmen del prado de Lácara', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0120)", "decision": "replace", "status": "MISSING", "reasoning": "The article (and es.wikipedia, same author line; no independent excavation date found, the Pilgrim Map and tourism pages only copy or give 3000-2500 BC) places the creation of the tomb at the turn of the 4th to the 3rd millennium BC, i.e. at -3000. The stored -4000 is the first year of the 4th millennium, but the source says the END of it, so it is not supported. The source itself straddles 3000 BC, so -3000 is the hedged turn it names.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0007", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The article dates the tomb to the end of the 4th or the beginning of the 3rd millennium BC, which straddles the 3000 BC band edge; no radiocarbon date is published and other sources (the Merida Consorcio: 5th or 4th millennium; tourism pages: 3000-2500 BC) disagree, so -3000 is not established as the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('1758f6e8-4518-43fb-a14a-1ce52caca683'::uuid, 'period_start', '-3000', '-4000', 'fields-wd5-2026-10-25p-s001-rollback:1758f6e8-4518-43fb-a14a-1ce52caca683:period_start', 'rollback of fields-wd5-2026-10-25p-s001: period_start ''-4000'' restored on Dolmen del prado de Lácara', '[{"source": "https://en.wikipedia.org/wiki/Dolmen_del_prado_de_L%C3%A1cara", "url": "https://en.wikipedia.org/wiki/Dolmen_del_prado_de_L%C3%A1cara", "quote": "towards the end of the 4th millennium BC or beginnings of the 3rd millennium BC", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0120)", "decision": "replace", "status": "MISSING", "reasoning": "The article (and es.wikipedia, same author line; no independent excavation date found, the Pilgrim Map and tourism pages only copy or give 3000-2500 BC) places the creation of the tomb at the turn of the 4th to the 3rd millennium BC, i.e. at -3000. The stored -4000 is the first year of the 4th millennium, but the source says the END of it, so it is not supported. The source itself straddles 3000 BC, so -3000 is the hedged turn it names.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0007", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The article dates the tomb to the end of the 4th or the beginning of the 3rd millennium BC, which straddles the 3000 BC band edge; no radiocarbon date is published and other sources (the Merida Consorcio: 5th or 4th millennium; tourism pages: 3000-2500 BC) disagree, so -3000 is not established as the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 8;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _fields_wd5_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'lat' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'lon' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'geom' THEN p.new_value::geometry IS NOT DISTINCT FROM p.old_value::geometry OR p.old_value IS NULL
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'site_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'source_url' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.old_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.old_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.old_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.old_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _fields_wd5_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.old_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD', 'Undated')
                WHEN 'site_type' THEN p.old_value NOT IN ('City', 'Town', 'Village', 'Settlement', 'Urban', 'Villa', 'City/town/settlement', 'Residence/villa/farmhouse', 'City/town/settlement, Pyramid complex', 'Castle', 'Citadel', 'Fort', 'Fortress', 'Military', 'Wall', 'Gate', 'Fortress/citadel', 'Castle/palace', 'Gate/archway/bridge', 'Fortification', 'Church', 'Mosque', 'Temple', 'Monastery', 'Sacred site', 'Sanctuary', 'Religious', 'Temple complex', 'Church/cathedral', 'Minaret/tower', 'Stone cross', 'Cemetery', 'Necropolis', 'Tomb', 'Burial', 'Funerary', 'Necropolis/tombs complex', 'Barrow', 'Mound/tumulus', 'Cairn', 'Elongated skulls', 'Megalithic', 'Megalithic stones', 'Megalithic structures', 'Megalithic statues', 'Megalithic walls', 'Stone circle', 'Dolmen', 'Standing stone', 'Henge', 'Timber circle', 'Polygonal masonry', 'Cave', 'Cave Structures', 'Rock relief/carving', 'Rock art', 'Petroglyphs', 'Sculptured stone', 'Cave Structures, Rock art', 'Geoglyphs', 'Road', 'Bridge', 'Mine', 'Quarry', 'Infrastructure', 'Road/avenue/trackway', 'Reservoir/aqueduct/canal', 'Mine/quarry', 'Earthwork', 'Well', 'Aqueduct', 'Bath', 'Harbor', 'Port', 'Underwater structures', 'Shipwreck', 'Monument', 'Memorial', 'Stadium', 'Theater', 'Theatre', 'Forum', 'Palace', 'Pyramid complex', 'Museum', 'Amphitheatre', 'Scheduled monument', 'Heritage site', 'Archaeological site', 'Site', 'Ruin', 'Inscription', 'Natural feature', 'Impact crater', 'Geological interest', 'Magnetic anomaly', 'Unknown')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _fields_wd5_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WD5/structured-fields', '2026-10-25p_fields-wd5-s001-rollback', r.change_key, 'one_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'WD5 field correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.new_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.new_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-25p_fields-wd5-s001-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-25p_fields-wd5-s001-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: this run stamp journalled % row(s) outside unified_sites.(lat, lon, geom, period_start, period_name, site_type, source_url)', bad;
    END IF;

    RAISE NOTICE 'WD5 field correction: % of % planned cell(s) changed and journalled over 4 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'period_start', '-2900'), ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'period_name', '3000 - 1500 BC'), ('0f1ec894-b1b1-40e9-9e00-bd193b316484'::uuid, 'period_start', '-300'), ('0f1ec894-b1b1-40e9-9e00-bd193b316484'::uuid, 'period_name', '500 BC - 1 AD'), ('10096963-03a9-4698-82b9-8c6386759359'::uuid, 'period_start', '-400'), ('10096963-03a9-4698-82b9-8c6386759359'::uuid, 'period_name', '500 BC - 1 AD'), ('1758f6e8-4518-43fb-a14a-1ce52caca683'::uuid, 'period_start', '-3000'), ('1758f6e8-4518-43fb-a14a-1ce52caca683'::uuid, 'period_name', '3000 - 1500 BC'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-25p_fields-wd5-s001-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN unified_sites u ON u.id = p.site_id
 WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS NOT DISTINCT FROM p.written::double precision
                WHEN 'lon' THEN u.lon IS NOT DISTINCT FROM p.written::double precision
                WHEN 'geom' THEN u.geom IS NOT DISTINCT FROM p.written::geometry
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM p.written::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM p.written::character varying
                WHEN 'site_type' THEN u.site_type IS NOT DISTINCT FROM p.written::character varying
                WHEN 'source_url' THEN u.source_url IS NOT DISTINCT FROM p.written::text
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _fields_wd5_plan left behind',
       (to_regclass('pg_temp._fields_wd5_plan') IS NOT NULL)::int::text
